const net = require("node:net");

const server = net.createServer((socket) => {   // runs once the handshake is done
  socket.end("hello");
});

server.listen(0, "127.0.0.1", () => {           // port 0: the OS picks a free port
  const { port } = server.address();
  // net.connect() triggers SYN, SYN-ACK, ACK inside the OS network stack.
  const client = net.connect(port, "127.0.0.1", () => console.log("connected"));
  client.on("data", (data) => {
    console.log(data.toString()); // hello
    client.end();
    server.close();
  });
});
